python - <<'EOF'
import math, time, itertools, numpy as np
x = np.random.rand(9000)
e = 2
def f1():
    flat = x.ravel(); return np.fromiter((math.pow(v, float(e)) for v in flat), dtype=np.float64, count=flat.size)
def f2():
    return np.fromiter(map(math.pow, x.ravel(), itertools.repeat(float(e))), dtype=np.float64, count=x.size)
uf = np.frompyfunc(math.pow, 2, 1)
def f3():
    return uf(x, float(e)).astype(np.float64)
def f4():
    return np.array(list(map(math.pow, x.tolist(), itertools.repeat(float(e)))))
for f in (f1, f2, f3, f4):
    t0 = time.perf_counter()
    for _ in range(50): r = f()
    print(f.__name__, (time.perf_counter()-t0)/50*1e3, "ms", np.array_equal(r, f1()))
print("x*x equal to pow?", np.array_equal(x*x, f1()))
EOF

